mapper.select:
SELECT F_GUID() posuuid /*主键*/, INFO.PROD_ID prodid,/*产品代码*/ INFO.ORG_CODE orgCode,/*产品所属机构代码*/ #{reportStartDate,jdbcType=DATE} startdate,/*报表开始日期*/ #{reportEndDate,jdbcType=DATE} enddate,/*报表结束日期*/ #{batchDate,jdbcType=DATE} bookdate,/*统计日期*/ (case INFO.IS_CONSTRACTE when 'Y' then '01' else '02' end) isConstracte,/*是否分级产品*/ INFO.PRODTYPE prodType,/*产品标识*/ INFO.IS_MARKET_FUND isMarketFund,/*货币市场基金*/ INFO.TRANSFER_TYPE transferType,/*转让类型*/ INFO.OPERATE_MODE operateMode,/*运行方式*/ INFO.RAISE_TYPE raisemode,/*募集方式*/ INFO.IVSTORIENTATION ivstorientation,/*投资性质*/ INFO.MANAGE_TYPE manageType,/*管理方式*/ INFO.FIDUCIARY_DUTY fiduciaryDuty,/*受托职责*/ INFO.VDATE,/*起息日*/ (case OPERATE_MODE when '03' then '0' when '04' then '0' else INFO.MDATE - INFO.VDATE end) TERM,/*合同期限*/ CASE WHEN ifnull((SELECT count(1) FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND NOT EXISTS (SELECT 1 FROM CHB_PRD_DEAL TMP WHERE ifnull(TMP.FPROD_ID,TMP.PROD_ID) = ifnull(D.FPROD_ID,D.PROD_ID) AND TMP.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND TMP.TRADE_TYPE = '16')),0) > 0 THEN '01' WHEN ifnull((SELECT count(1) FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16'),0) > 0 THEN '02' WHEN ifnull((SELECT count(1) FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE}),0) = 0 THEN '03' ELSE NULL END DURATIONFLAG,/*存续状态*/ DEAL.BUY_PLACE buyPlace,/*销售区域*/ CASE WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) = (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '01' WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) > (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '02' WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) < (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '03' WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) BETWEEN #{reportStartDate,jdbcType=DATE} and #{reportEndDate,jdbcType=DATE} AND NOT EXISTS (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '04' ELSE NULL END PAYSTATUS,/*兑付状态*/ DEAL.CCY,/*币种*/ DEAL.CUSTOMER_TYPE2 customerType2,/*客户二级类型*/ CASE WHEN INFO.PRODTYPE = 'N' THEN DEAL.QM_PRINCE * ifnull((SELECT PROD_VALUE FROM (SELECT FPROD_ID,PROD_ID,PROD_VALUE if (@PROD_ID = PROD_ID, @rank := @rank + 1,@rank :=1) as MY_RANK, (@PROD_ID := PROD_ID) PROD_ID FROM CHB_PRD_PERIODYIELD, (SELECT @rank := 0, @PROD_ID := null) b WHERE CHANGE_DATE <= #{reportEndDate,jdbcType=DATE} AND CHANG_TYPE='01' order by PROD_ID, CHANGE_DATE desc ) WHERE 1=1 AND ifnull(FPROD_ID,PROD_ID) = INFO.PROD_ID limit 1 ) ,1) ELSE DEAL.QM_PRINCE END ENDAMTSUM_OTH,/*期末余额*/ DEAL.MJ_PRINCE DIRTYAMTSUM,/*募集金额*/ DEAL.DF_PRINCE REDAMT,/*兑付金额*/ DEAL.QM_PRINCE ENDQTYSUM,/*剩余份额*/ CASE WHEN INFO.OPERATE_MODE IN ('01','02') THEN GREATEST(INFO.MDATE - #{reportEndDate,jdbcType=DATE},0) ELSE ( CASE WHEN (SELECT count(1) FROM CHB_PRD_OPENSCH CSCH WHERE CSCH.PROD_ID = INFO.PROD_ID)=0 THEN 1 ELSE GREATEST( ifnull((SELECT MIN(SCH.OPEN_START) FROM CHB_PRD_OPENSCH SCH WHERE SCH.PROD_ID = INFO.PROD_ID AND SCH.OPEN_START > #{reportEndDate,jdbcType=DATE} ) ,INFO.MDATE) - #{reportEndDate,jdbcType=DATE} ,0) END ) END END_DAYS/*剩余期限*/ FROM CHB_PRD_BASEINFO INFO
LEFT JOIN ( SELECT PROD_ID, CCY, CUSTOMER_TYPE2, BUY_PLACE, SUM(MJ_PRINCE) MJ_PRINCE, SUM(DF_PRINCE) DF_PRINCE, SUM(QM_PRINCE) QM_PRINCE FROM ( SELECT ifnull(DL.FPROD_ID,DL.PROD_ID) PROD_ID, CCY, CUSTOMER_TYPE2, BUY_PLACE, DL.SETTDATE_DATE, CASE WHEN DL.SETTDATE_DATE BETWEEN #{reportStartDate,jdbcType=DATE} AND #{reportEndDate,jdbcType=DATE} THEN SUM(CASE WHEN DL.trade_type IN('01','02','05') THEN DL.TRADE_PRINCE ELSE 0 END ) ELSE 0 END MJ_PRINCE, CASE WHEN DL.SETTDATE_DATE BETWEEN #{reportStartDate,jdbcType=DATE} AND #{reportEndDate,jdbcType=DATE} THEN SUM(CASE WHEN DL.trade_type IN('03','16','17') THEN DL.TRADE_PRINCE ELSE 0 END ) ELSE 0 END DF_PRINCE, SUM( case when DL.TRADE_TYPE in ('01','02','05','14') then DL.TRADE_QTY else -1 * DL.TRADE_QTY end ) QM_PRINCE FROM CHB_PRD_DEAL DL WHERE DL.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND DL.TRADE_TYPE != '04'
AND ifnull(DL.FPROD_ID,DL.PROD_ID) IN
#{prodid,jdbcType=VARCHAR}
/*历史到期产品不统计*/ AND NOT EXISTS(SELECT 1 FROM CHB_PRD_DEAL D WHERE D.TRADE_TYPE = '16' AND ifnull(D.FPROD_ID,D.PROD_ID) = ifnull(DL.FPROD_ID,DL.PROD_ID) AND D.SETTDATE_DATE < #{reportStartDate,jdbcType=DATE}) GROUP BY ifnull(DL.FPROD_ID,DL.PROD_ID),CCY,CUSTOMER_TYPE2,BUY_PLACE,DL.SETTDATE_DATE ) GROUP BY PROD_ID,CCY,CUSTOMER_TYPE2,BUY_PLACE )DEAL ON DEAL.PROD_ID = INFO.PROD_ID
WHERE INFO.FPROD_ID IS NULL /*非保本*/ AND INFO.PROFIT_TYPE = '03'
AND INFO.PROD_ID IN
#{prodid,jdbcType=VARCHAR}
AND INFO.VDATE <= #{reportEndDate,jdbcType=DATE} /*历史到期产品不统计*/ AND NOT EXISTS(SELECT 1 FROM CHB_PRD_DEAL D WHERE D.TRADE_TYPE = '16' AND ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE < #{reportStartDate,jdbcType=DATE})

select * from PBC_MONTH_PRD_POSITION b inner join chb_prd_baseinfo info on b.prodid = info.prod_id
where DATE_FORMAT(b.ENDDATE,'%Y-%m-%d') = #{bookDate,jdbcType=VARCHAR}
and info.profit_type = '03' /*过滤非保本产品*/

mapper.sql:
/*头寸计算：几个金额的计算，以产品id，币种，客户二级类型，销售区域分组*/ select ds.* ,ifnull(pv.prod_value,1) prod_value ,/*产品最新净值*/ pv.ccy yieldccy/*报价币种*/ from ( SELECT prodid, ccy, customer_type2, buy_place, SUM(dirtyamtsum) dirtyamtsum, /*当期募集金额*/ SUM(redamt) redamt, /*当期兑付金额*/ SUM(raiseqty) raiseqty, /*当期募集份额*/ SUM(payqty) payqty, /*当期兑付份额*/ SUM(redcost) redcost, /*当期到期本金*/ SUM(endcost) endcost, /*剩余成本*/ SUM(endqtysum) endqtysum /*期末份额*/ FROM ( /*上周期头寸*/ SELECT prodid, ccy, customer_type2, buy_place, 0 dirtyamtsum, 0 redamt, 0 raiseqty, 0 payqty, 0 redcost, endcost, endqtysum FROM pbc_month_prd_position WHERE ENDDATE between DATE_ADD(#{reportStartDate,jdbcType=DATE}, interval -1 month) and #{reportStartDate,jdbcType=DATE} UNION ALL /*本周期头寸*/ SELECT ifnull(dl.fprod_id, dl.prod_id) prodid, ccy, typemap.objfield1 customer_type2, buy_place, SUM( CASE WHEN dl.trade_type IN('01', '02', '14'
/***根据参数判断是否添加红利再投**/ ,'05'
) THEN dl.trade_prince ELSE 0 END ) dirtyamtsum, SUM( CASE WHEN dl.trade_type IN('03', '04', '15', '16', '17'
/***根据参数判断是否添加红利再投**/ ,'05'
) THEN /*加上 04收益分配，05红利再投的交易金额与人行确认不需统计*/ dl.trade_prince ELSE 0 END ) redamt, SUM( CASE WHEN dl.trade_type IN('01', '02', '05','14'
/***根据参数判断是否添加红利再投**/ ,'05'
) THEN dl.trade_qty ELSE 0 END ) raiseqty, SUM( CASE WHEN dl.trade_type IN('03', '15','16', '17') THEN dl.trade_qty ELSE 0 END ) payqty, SUM( CASE WHEN dl.trade_type = '16' THEN dl.trade_cost ELSE 0 END ) redcost, SUM(CASE WHEN dl.trade_type IN ('01','02','05','14') THEN dl.trade_cost ELSE -1 * dl.trade_cost END) endcost, SUM(CASE WHEN dl.trade_type IN ('01','02','05','14') THEN dl.trade_qty ELSE - 1 * dl.trade_qty END) endqtysum FROM chb_prd_deal dl
left join chb_type_mapping_ex typemap on dl.CUSTOMER_TYPE2=typemap.srcfield1 and typemap.mappingcode='PBC_MONTH_REPORT_CUSTOMER_TYPE2'
WHERE 1 = 1 AND dl.settdate_date BETWEEN #{reportStartDate,jdbcType=DATE} AND #{reportEndDate,jdbcType=DATE} /*AND dl.trade_type != '04'*/ AND dl.status in ('E','M') GROUP BY ifnull(dl.fprod_id, dl.prod_id), ccy, typemap.objfield1, buy_place ) bb GROUP BY prodid, ccy, customer_type2, buy_place ) ds /*产品净值*/ LEFT JOIN ( SELECT prod_value, ifnull(fprod_id, prod_id) prod_id,ccy FROM ( SELECT RANK() OVER(PARTITION BY prod_id,ifnull(ccy,'CNY')ORDER BY change_date DESC) my_rank, fprod_id, prod_id, ifnull(ccy,'CNY') ccy, prod_value FROM chb_prd_periodyield WHERE 1 = 1 and CHANGE_DATE <= #{reportEndDate,jdbcType=DATE} AND chang_type = '01' AND status in ('E' ,'M')/*收益率添加修改状态*/ ) cc WHERE my_rank = 1 ) pv ON ds.prodid = pv.prod_id

/* 产品信息：兑付状态实际需要的到期日*/
SELECT * FROM (
SELECT T.PRODUUID, T.REALCDATE, t.fprod_id, t.status,t.vdate, row_number() over (partition by t.PRODUUID order by T.REALCDATE) NUM FROM
(
SELECT info.PRODUUID, VH.CDATE REALCDATE, info.fprod_id, info.status, info.vdate
FROM CHB_PRD_BASEINFO INFO,  VAL_VW_MST_HOLIDAY VH
WHERE IS_HOLIDAY = '0'
AND VH.CDATE > INFO.MDATE
AND VH.TRADE_CALENDAR_ID = info.CALENDAR_ID
) T
)AS T1
WHERE NUM = #{days,jdbcType=INTEGER}
and fprod_id IS NULL
and status in ('E','M')
AND VDATE <= #{reportEndDate,jdbcType=DATE}

/*产品信息：产品基本信息，产品最新净值，产品开放计划信息，产品的交易信息*/ SELECT info.prod_id, info.org_code, info.is_constracte,/*是否分级产品*/ info.prodtype,/*产品标识*/ /*货币市场基金*/ info.cash_mana_cate as is_market_fund,
info.transfer_type,/*转让类型*/ info.operate_mode,/*运行方式*/ info.raise_type,/*募集方式*/ info.ivstorientation,/*投资性质*/ info.manage_type,/*管理方式*/ info.fiduciary_duty,/*受托职责*/ info.vdate,/*起息日*/ info.mdate,/*合同期限*/ info.terminatedate, /*终止日期*/ ifnull(sch.plancounts,0) plancounts, /*开放计划条数*/ sch.minopenstart minopenstart, /*最小开放日*/ ifnull(dealstat.dealcounts,0) dealcounts, /*交易条数*/ ifnull(dealstat.terminatecounts,0) terminatecounts, /*终止交易条数*/ dealstat.settdate_date, /*终止交易确认日*/ info.issuing_status, /*存续状态*/ ifnull(tem.REALCDATE, INFO.MDATE) REALMDATE /*修正到期日*/ FROM /*产品基本信息*/ chb_prd_baseinfo info /*开放计划*/ left join ( SELECT a.prod_id, ifnull(a.plancounts,0) plancounts, b.minopenstart FROM ( SELECT COUNT(1) plancounts, prod_id FROM chb_prd_opensch WHERE status in ('E','M') GROUP BY prod_id ) a LEFT JOIN ( SELECT MIN(open_start) minopenstart, prod_id FROM chb_prd_opensch WHERE status in ('E','M') AND open_start > #{reportEndDate,jdbcType=DATE} GROUP BY prod_id ) b ON a.prod_id = b.prod_id ) sch on sch.prod_id = info.prod_id /*交易统计：产品的交易条数，16交易的条数，16交易的确认日*/ left join( SELECT a.prod_id, ifnull(a.dealcounts,0) dealcounts, ifnull(b.terminatecounts,0) terminatecounts, b.settdate_date FROM ( SELECT ifnull(fprod_id, prod_id) prod_id, COUNT(1) dealcounts FROM chb_prd_deal WHERE status in ('E','M') and settdate_date<= #{reportEndDate,jdbcType=DATE} GROUP BY ifnull(fprod_id, prod_id) ) a LEFT JOIN ( SELECT ifnull(fprod_id, prod_id) prod_id, MAX(settdate_date) settdate_date, COUNT(1) terminatecounts FROM chb_prd_deal WHERE status in ('E','M') AND trade_type = '16' and settdate_date<= #{reportEndDate,jdbcType=DATE} GROUP BY ifnull(fprod_id, prod_id) ) b ON a.prod_id = b.prod_id ) dealstat on dealstat.prod_id=info.prod_id left join () tem on info.PRODUUID = tem.PRODUUID WHERE info.fprod_id IS NULL and info.status in ('E','M')
AND INFO.PROD_ID IN
null) OR INFO.PROD_ID in (
#{item}
AND INFO.VDATE <= #{reportEndDate,jdbcType=DATE} /*历史到期产品不统计*/ AND NOT EXISTS ( SELECT 1 FROM chb_prd_deal d WHERE d.trade_type = '16' AND ifnull(d.fprod_id, d.prod_id) = info.prod_id and status in ('E','M') AND D.SETTDATE_DATE < #{reportStartDate,jdbcType=DATE} )

